      {/* 自定义内容 */}
      {children}

      {/* 按钮组 - 交错入场 */}
      <div className="flex gap-3 mt-5">
        <button
          onClick={onNewGame}
          className="px-8 py-3 bg-ink text-paper font-serif-sc text-sm tracking-[4px] hover:bg-ink-light transition-colors hover-lift"
